function sceneForRun(ctx,run){status(run);const urgent=['medical','hydrate','sleep'];const available=g=>g.test(run)&&(!g.once||run.gateSeen?.[g.id]===undefined)&&(run.stage-(run.gateSeen?.[g.id]??-100)>=4)&&(!g.chance||hash(run.seed+run.stage*131+g.id.length*31)%100<g.chance);let gate=GATES.find(g=>urgent.includes(g.id)&&available(g));if(!gate&&!ctx.chain)gate=GATES.find(available);return gate?{...gate.scene,chapter:CHAPTERS[Math.floor(ctx.stage/8)],month:Math.floor(ctx.stage/8)+1,family:FAMILIES[ctx.family],gate:gate.id,sceneKey:`${gate.scene.location}:gate:${gate.id}:${encode(ctx)}`}:scenario(ctx)}
